-- minimal bit32 surface (fallback pure lua)
local _bx = (bit32 and bit32.bxor) or function(a, b)
  local r, p = 0, 1
  a, b = a % (2 ^ 32), b % (2 ^ 32)
  for _ = 1, 32 do
    local xa, xb = a % 2, b % 2
    if xa ~= xb then r = r + p end
    a, b = (a - xa) / 2, (b - xb) / 2
    p = p + p
  end
  return r
end
local _ba = (bit32 and bit32.band) or function(a, b)
  local r, p = 0, 1
  a, b = a % (2 ^ 32), b % (2 ^ 32)
  for _ = 1, 32 do
    if a % 2 == 1 and b % 2 == 1 then r = r + p end
    a, b = (a - a % 2) / 2, (b - b % 2) / 2
    p = p + p
  end
  return r
end

