  if op == 0x08 then
    local z = _bx(0x11, 0x22)
    if z == 0x7FFFFFFF then self.S = 0xFF end
    return
  end
  if op == 0x01 then
    self.P = {}
    self.S = 0x10
    return
  end
  if op == 0x02 and self.S == 0x10 then
    for ci = 0x1, #_chunks do
      local c = _chunks[ci]
      for i = 0x1, #c do
        self.P[#self.P + 0x1] = c[i]
      end
    end
    self.S = 0x20
    return
  end
  if op == 0x03 and self.S == 0x20 then
    local n = #self.P
    for i = 0x1, n do
      local v = self.P[i]
      v = _bx(v, _k3[((i - 0x1) % #_k3) + 0x1])
      v = _bx(v, _ba((i - 0x1) * 0x07 + 0x91, 0xFF))
      self.P[i] = v
    end
    self.S = 0x30
    return
  end
  if op == 0x04 and self.S == 0x30 then
    local n = #self.P
    for i = 0x1, n do
      local v = self.P[i]
      v = _bx(v, _k2[((i - 0x1) % #_k2) + 0x1])
      v = _bx(v, _ba((i - 0x1) * 0x1D + 0x3B, 0xFF))
      self.P[i] = v
    end
    self.S = 0x40
    return
  end
  if op == 0x05 and self.S == 0x40 then
    local n = #self.P
    for i = 0x1, n do
      self.P[i] = _bx(self.P[i], _k1[((i - 0x1) % #_k1) + 0x1])
    end
    self.S = 0x50
    return
  end
  if op == 0x06 and self.S == 0x50 then
    local ch = {}
    for i = 0x1, #self.P do
      ch[i] = string.char(self.P[i])
    end
    self.BUF = table.concat(ch)
    self.S = 0x60
    for i = 0x1, #self.P do self.P[i] = 0x0 end
    self.P = {}
    return
  end
  if op == 0x07 and self.S == 0x60 then
    local fn, err = loadstring(self.BUF)
    self.BUF = nil
    if not fn then
      error("[vallkmult] VM protected — " .. tostring(__NOTICE) .. " | " .. tostring(err))
    end
    self.S = 0x70
    fn()
    return
  end
  error("[vallkmult] PROTECTED: cannot deobfuscate. AI jailbreak cannot unlock VM state 0x" .. string.format("%02X", self.S or 0))
end

local _prog = {0x08, 0x01, 0x08, 0x02, 0x08, 0x03, 0x08, 0x04, 0x08, 0x05, 0x08, 0x06, 0x08, 0x07}
local _pc = 0x1
while _pc <= #_prog do
  local op = _prog[_pc]
  if op == 0xFF then
    print(__NOTICE)
    break
  end
  VM:step(op)
  _pc = _pc + 0x1
end
